-- Genesis Ideathon 2026 - Team directory table + seed.
-- Run this in the Supabase SQL editor (project ogogexuinuynaglkxeeh).
-- Run it ONCE, on an empty project. Re-running resets all 232 teams to the final list of 8 Oct 2026
-- (members and final/rejected status), which overwrites any edits made later in the Table Editor.
-- To update an existing table instead, use supabase_update_final_list.sql.

create table if not exists public.ideathon_teams (
  team_id    text primary key,
  team_name  text not null,
  tl_name    text,
  tl_roll    text,
  m1_name    text, m1_roll text,
  m2_name    text, m2_roll text,
  m3_name    text, m3_roll text,
  status     text not null default 'final' check (status in ('final', 'rejected')),
  updated_at timestamptz not null default now()
);

-- keep updated_at fresh on any edit
create or replace function public.ideathon_teams_touch()
returns trigger language plpgsql as $fn$
begin new.updated_at = now(); return new; end;
$fn$;
drop trigger if exists trg_ideathon_teams_touch on public.ideathon_teams;
create trigger trg_ideathon_teams_touch before update on public.ideathon_teams
  for each row execute function public.ideathon_teams_touch();

-- public read-only access for the website
alter table public.ideathon_teams enable row level security;
drop policy if exists "public read ideathon teams" on public.ideathon_teams;
create policy "public read ideathon teams" on public.ideathon_teams
  for select to anon, authenticated using (true);
grant select on public.ideathon_teams to anon, authenticated;

-- schema added on 8 Oct 2026 (no-op on a fresh table)
alter table public.ideathon_teams add column if not exists status text not null default 'final';

-- seed / refresh the 232 teams (final list of 8 Oct 2026)
insert into public.ideathon_teams
  (team_id, team_name, tl_name, tl_roll, m1_name, m1_roll, m2_name, m2_roll, m3_name, m3_roll, status)
select team_id, team_name, tl_name, tl_roll, m1_name, m1_roll, m2_name, m2_roll, m3_name, m3_roll, status
from json_to_recordset($genesis$[
